function*gen(){yield 1,yield 2,yield 3}const g=gen();function*iterate(e){for(let o of e)yield o}console.log(g.next().value),console.log(g.next().value),console.log(g.next().value);const it=iterate(["Oscar","Omar","Ana","Lucia","Juan"]);console.log(it.next().value),console.log(it.next().value),console.log(it.next().value),console.log(it.next().value),console.log(it.next().value),console.log(it.next().value);